    "description": "The unique identifier of the policy to be updated.",
    "required": true
   },
   {
    "name": "policy_name",
    "type": "string",
    "description": "The new name of the policy.",
    "required": false
   },
   {
    "name": "policy_description",
    "type": "string",
    "description": "The new description of the policy.",
    "required": false
   },
